import { test, expect } from '@playwright/test';

test.describe('Debounced Search Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should not trigger search on every keystroke', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await searchInput.fill('test');
    await page.waitForTimeout(100); // Wait for less than 300ms
    await expect(page.getByText(/loading/i)).not.toBeVisible(); // Ensure loading is not visible

    await searchInput.fill('test search');
    await page.waitForTimeout(100); // Wait for less than 300ms
    await expect(page.getByText(/loading/i)).not.toBeVisible(); // Ensure loading is not visible
  });

  test('should trigger search after 300ms of inactivity', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await searchInput.fill('test search');
    await page.waitForTimeout(300); // Wait for 300ms
    await expect(page.getByText(/loading/i)).toBeVisible(); // Ensure loading is visible
    await expect(page.getByText(/results for "test search"/i)).toBeVisible(); // Ensure results are displayed
  });
});
